#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXB 100005
#define LOGN 18
#define INF 1000000000

typedef struct {
    int u, v, w;
} Edge;

typedef struct {
    int to, weight, next;
} AdjEdge;

Edge edges[MAXB];
int head[MAXN];
AdjEdge adj[2 * MAXN];
int edge_cnt = 0;

void add_edge(int u, int v, int w) {
    adj[edge_cnt].to = v;
    adj[edge_cnt].weight = w;
    adj[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int cmp_edges(const void *a, const void *b) {
    Edge *e1 = (Edge *)a;
    Edge *e2 = (Edge *)b;
    return e2->w - e1->w;
}

int parent_dsu[MAXN];

int find_dsu(int i) {
    if (parent_dsu[i] == i)
        return i;
    return parent_dsu[i] = find_dsu(parent_dsu[i]);
}

void union_dsu(int i, int j) {
    int root_i = find_dsu(i);
    int root_j = find_dsu(j);
    if (root_i != root_j) {
        parent_dsu[root_i] = root_j;
    }
}

int up[MAXN][LOGN];
int min_edge[MAXN][LOGN];
int depth[MAXN];
int queue_nodes[MAXN];

void bfs(int root, int n) {
    for (int i = 1; i <= n; i++) {
        depth[i] = -1;
    }
    int front = 0, back = 0;
    queue_nodes[back++] = root;
    depth[root] = 0;
    up[root][0] = root;
    min_edge[root][0] = INF;

    while (front < back) {
        int u = queue_nodes[front++];
        for (int e = head[u]; e != -1; e = adj[e].next) {
            int v = adj[e].to;
            int w = adj[e].weight;
            if (depth[v] == -1) {
                depth[v] = depth[u] + 1;
                up[v][0] = u;
                min_edge[v][0] = w;
                queue_nodes[back++] = v;
            }
        }
    }

    for (int j = 1; j < LOGN; j++) {
        for (int i = 1; i <= n; i++) {
            up[i][j] = up[up[i][j - 1]][j - 1];
            int m1 = min_edge[i][j - 1];
            int m2 = min_edge[up[i][j - 1]][j - 1];
            min_edge[i][j] = (m1 < m2) ? m1 : m2;
        }
    }
}

int query(int u, int v) {
    int ans = INF;
    if (depth[u] < depth[v]) {
        int temp = u;
        u = v;
        v = temp;
    }

    for (int j = LOGN - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            if (min_edge[u][j] < ans) ans = min_edge[u][j];
            u = up[u][j];
        }
    }

    if (u == v) return ans;

    for (int j = LOGN - 1; j >= 0; j--) {
        if (up[u][j] != up[v][j]) {
            if (min_edge[u][j] < ans) ans = min_edge[u][j];
            if (min_edge[v][j] < ans) ans = min_edge[v][j];
            u = up[u][j];
            v = up[v][j];
        }
    }

    if (min_edge[u][0] < ans) ans = min_edge[u][0];
    if (min_edge[v][0] < ans) ans = min_edge[v][0];

    return ans;
}

int main() {
    int n, b;
    if (scanf("%d %d", &n, &b) != 2) return 0;

    for (int i = 0; i < b; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    qsort(edges, b, sizeof(Edge), cmp_edges);

    for (int i = 1; i <= n; i++) {
        parent_dsu[i] = i;
        head[i] = -1;
    }

    int edges_added = 0;
    for (int i = 0; i < b; i++) {
        int u = edges[i].u;
        int v = edges[i].v;
        int w = edges[i].w;
        if (find_dsu(u) != find_dsu(v)) {
            union_dsu(u, v);
            add_edge(u, v, w);
            add_edge(v, u, w);
            edges_added++;
            if (edges_added == n - 1) break;
        }
    }

    bfs(1, n);

    int c;
    if (scanf("%d", &c) != 1) return 0;

    while (c--) {
        int u, v;
        scanf("%d %d", &u, &v);
        printf("%d\n", query(u, v));
    }

    return 0;
}
